(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-trap-c6-advanced-1"]={"id":"unit22-trap-c6-advanced-1","unitId":"2-2","chapterIds":["2-2"],"unitType":"advanced","group":"선지 변형 유형 · 주체","name":"심화 5지선다 1","level":"심화","desc":"2-2단원 · 주체","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"주체","parts":[{"name":"U22-02 · 내용의 타당성","items":[{"paragraphCount":1,"readingLabel":"교과서 49쪽 개념 발췌 정리","sourceLabel":"비판적 읽기와 다양한 읽기 방법 · 교과서 49쪽 개념 발췌 정리","passage":"[비판적 읽기와 다양한 읽기 방법 · 교과서 49쪽 개념 발췌 정리]\n비판적 읽기는 글의 내용과 필자의 생각을 무조건 수용하지 않고, 글에 제시된 내용이 올바른지 따져 가며 읽는 것이다. 내용의 타당성은 글에 나타난 주장이나 의견, 근거 등 글의 내용이 옳고 정확한지 살피는 기준이다. 관점의 공정성은 필자가 글의 내용을 한쪽으로 치우치지 않고 균형 있게 다루는지 판단하는 기준이다. 표현 방법의 적절성은 글의 목적과 내용에 비추어 표현 방법이 효과적이고 적절한지 평가하는 기준이다. 비판적 독자는 글에 반영된 사회·문화적 이념이 현재 우리의 상황에서 수용할 수 있는 것인지 판단한다. 창의적 읽기는 문제 상황을 비판적으로 이해하고 유연한 사고로 발상을 전환하며 새로운 대안을 탐구하는 읽기이다. 감상적 읽기는 글의 내용이나 필자의 생각에 공감하며 감동과 즐거움을 얻는 읽기이며, 서로 다른 감상을 공유하여 이해를 풍부하게 할 수 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["주체"],"id":"U22-02-S1","type":"mc","sent":"교과서 49쪽 개념 발췌 정리의 내용과 맞는 설명은?","options":["내용의 타당성은 글이 한쪽 입장에 치우쳤는지 보는 기준이다.","내용의 타당성을 살필 때는 글의 주장과 근거가 옳고 정확한지 확인한다.","내용의 타당성을 살필 때는 비유와 운율만 확인한다.","글의 주장이 옳은지는 따지지 않고 그대로 믿어야 한다.","내용의 타당성은 표현이 얼마나 새로운지만 보는 기준이다."],"answer":"내용의 타당성을 살필 때는 글의 주장과 근거가 옳고 정확한지 확인한다.","why":"타당성을 판단할 때는 주장이 맞는지, 주장을 뒷받침하는 근거가 정확한지 확인해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","choiceReviews":{"내용의 타당성을 살필 때는 글의 주장과 근거가 옳고 정확한지 확인한다.":{"reason":"타당성을 판단할 때는 주장이 맞는지, 주장을 뒷받침하는 근거가 정확한지 확인해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[]},"내용의 타당성은 글이 한쪽 입장에 치우쳤는지 보는 기준이다.":{"reason":"바르게 고치면: 관점의 공정성은 글이 한쪽 입장에 치우쳤는지 보는 기준이다.\n타당성을 판단할 때는 주장이 맞는지, 주장을 뒷받침하는 근거가 정확한지 확인해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":0,"end":9,"before":"내용의 타당성은 ","after":"관점의 공정성은 "}]},"내용의 타당성을 살필 때는 비유와 운율만 확인한다.":{"reason":"바르게 고치면: 내용의 타당성을 살필 때는 주장과 근거가 옳고 정확한지 확인한다.\n타당성을 판단할 때는 주장이 맞는지, 주장을 뒷받침하는 근거가 정확한지 확인해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":15,"end":23,"before":"비유와 운율만 ","after":"주장과 근거가 옳고 정확한지 "}]},"글의 주장이 옳은지는 따지지 않고 그대로 믿어야 한다.":{"reason":"바르게 고치면: 글의 주장이 옳은지 따져야 한다.\n타당성을 판단할 때는 주장이 맞는지, 주장을 뒷받침하는 근거가 정확한지 확인해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":7,"end":27,"before":"옳은지는 따지지 않고 그대로 믿어야 ","after":"옳은지 따져야 "}]},"내용의 타당성은 표현이 얼마나 새로운지만 보는 기준이다.":{"reason":"바르게 고치면: 내용의 타당성은 주장과 근거가 옳고 정확한지 보는 기준이다.\n타당성을 판단할 때는 주장이 맞는지, 주장을 뒷받침하는 근거가 정확한지 확인해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":9,"end":23,"before":"표현이 얼마나 새로운지만 ","after":"주장과 근거가 옳고 정확한지 "}]}},"pageSpecificReasons":true,"evidence":{"title":"내용의 타당성","statement":"내용의 타당성을 살필 때는 글의 주장과 근거가 옳고 정확한지 확인한다.","explanation":"타당성을 판단할 때는 주장이 맞는지, 주장을 뒷받침하는 근거가 정확한지 확인해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","valid":["D22:2"],"sources":[{"id":"D22","title":"비판적 읽기와 다양한 읽기 방법","label":"교과서 49쪽 개념 발췌 정리","sentences":[{"id":"D22:1","text":"비판적 읽기는 글의 내용과 필자의 생각을 무조건 수용하지 않고, 글에 제시된 내용이 올바른지 따져 가며 읽는 것이다.","paragraph":0,"memberIds":["D22:1"],"topic":"비판적 읽기"},{"id":"D22:2","text":"내용의 타당성은 글에 나타난 주장이나 의견, 근거 등 글의 내용이 옳고 정확한지 살피는 기준이다.","paragraph":0,"memberIds":["D22:2"],"topic":"내용의 타당성"},{"id":"D22:3","text":"관점의 공정성은 필자가 글의 내용을 한쪽으로 치우치지 않고 균형 있게 다루는지 판단하는 기준이다.","paragraph":0,"memberIds":["D22:3"],"topic":"관점의 공정성"},{"id":"D22:4","text":"표현 방법의 적절성은 글의 목적과 내용에 비추어 표현 방법이 효과적이고 적절한지 평가하는 기준이다.","paragraph":0,"memberIds":["D22:4"],"topic":"표현 방법의 적절성"},{"id":"D22:5","text":"비판적 독자는 글에 반영된 사회·문화적 이념이 현재 우리의 상황에서 수용할 수 있는 것인지 판단한다.","paragraph":0,"memberIds":["D22:5"],"topic":"사회·문화적 이념"},{"id":"D22:6","text":"창의적 읽기는 문제 상황을 비판적으로 이해하고 유연한 사고로 발상을 전환하며 새로운 대안을 탐구하는 읽기이다.","paragraph":0,"memberIds":["D22:6"],"topic":"창의적 읽기"},{"id":"D22:7","text":"감상적 읽기는 글의 내용이나 필자의 생각에 공감하며 감동과 즐거움을 얻는 읽기이며, 서로 다른 감상을 공유하여 이해를 풍부하게 할 수 있다.","paragraph":0,"memberIds":["D22:7"],"topic":"감상적 읽기"}]}]},"editorSourceVersion":"c4a7a005ca4094f4fb4e7fb56f8ce9871fcb91807f2f24e3de794f86f7c2c96d"}]},{"name":"U22-05 · 사회·문화적 이념 평가","items":[{"paragraphCount":1,"readingLabel":"교과서 49쪽 개념 발췌 정리","sourceLabel":"비판적 읽기와 다양한 읽기 방법 · 교과서 49쪽 개념 발췌 정리","passage":"[비판적 읽기와 다양한 읽기 방법 · 교과서 49쪽 개념 발췌 정리]\n비판적 읽기는 글의 내용과 필자의 생각을 무조건 수용하지 않고, 글에 제시된 내용이 올바른지 따져 가며 읽는 것이다. 내용의 타당성은 글에 나타난 주장이나 의견, 근거 등 글의 내용이 옳고 정확한지 살피는 기준이다. 관점의 공정성은 필자가 글의 내용을 한쪽으로 치우치지 않고 균형 있게 다루는지 판단하는 기준이다. 표현 방법의 적절성은 글의 목적과 내용에 비추어 표현 방법이 효과적이고 적절한지 평가하는 기준이다. 비판적 독자는 글에 반영된 사회·문화적 이념이 현재 우리의 상황에서 수용할 수 있는 것인지 판단한다. 창의적 읽기는 문제 상황을 비판적으로 이해하고 유연한 사고로 발상을 전환하며 새로운 대안을 탐구하는 읽기이다. 감상적 읽기는 글의 내용이나 필자의 생각에 공감하며 감동과 즐거움을 얻는 읽기이며, 서로 다른 감상을 공유하여 이해를 풍부하게 할 수 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["주체"],"id":"U22-05-S1","type":"mc","sent":"교과서 49쪽 개념 발췌 정리의 내용과 맞는 설명은?","options":["글쓴이가 유명하면 그 사람의 이념을 그대로 받아들인다.","글에 담긴 이념은 무조건 받아들여야 한다.","이념을 평가할 때는 오늘날 우리 상황을 생각할 필요가 없다.","글에 담긴 생각보다 글자의 모양을 보고 이념을 판단한다.","글에 담긴 사회·문화적 이념도 따져 읽는다. 오늘날 우리 상황에서 받아들일 수 있는지 판단한다."],"answer":"글에 담긴 사회·문화적 이념도 따져 읽는다. 오늘날 우리 상황에서 받아들일 수 있는지 판단한다.","why":"글에 담긴 사회·문화적 이념도 무조건 믿지는 않아요. 지금 우리가 살아가는 상황에 맞는 생각인지 따져 보아야 해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","choiceReviews":{"글에 담긴 사회·문화적 이념도 따져 읽는다. 오늘날 우리 상황에서 받아들일 수 있는지 판단한다.":{"reason":"글에 담긴 사회·문화적 이념도 무조건 믿지는 않아요. 지금 우리가 살아가는 상황에 맞는 생각인지 따져 보아야 해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[]},"글쓴이가 유명하면 그 사람의 이념을 그대로 받아들인다.":{"reason":"바르게 고치면: 글쓴이가 유명해도 그 사람의 이념이 오늘날 우리 상황에 맞는지 판단한다.\n글에 담긴 사회·문화적 이념도 무조건 믿지는 않아요. 지금 우리가 살아가는 상황에 맞는 생각인지 따져 보아야 해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":5,"end":10,"before":"유명하면 ","after":"유명해도 "},{"start":16,"end":30,"before":"이념을 그대로 받아들인다.","after":"이념이 오늘날 우리 상황에 맞는지 판단한다."}]},"글에 담긴 이념은 무조건 받아들여야 한다.":{"reason":"바르게 고치면: 글에 담긴 이념은 받아들일 수 있는지 판단해야 한다.\n글에 담긴 사회·문화적 이념도 무조건 믿지는 않아요. 지금 우리가 살아가는 상황에 맞는 생각인지 따져 보아야 해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":10,"end":20,"before":"무조건 받아들여야 ","after":"받아들일 수 있는지 판단해야 "}]},"이념을 평가할 때는 오늘날 우리 상황을 생각할 필요가 없다.":{"reason":"바르게 고치면: 이념을 평가할 때는 오늘날 우리 상황을 생각해야 한다.\n글에 담긴 사회·문화적 이념도 무조건 믿지는 않아요. 지금 우리가 살아가는 상황에 맞는 생각인지 따져 보아야 해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":22,"end":33,"before":"생각할 필요가 없다.","after":"생각해야 한다."}]},"글에 담긴 생각보다 글자의 모양을 보고 이념을 판단한다.":{"reason":"바르게 고치면: 글에 담긴 생각을 보고 이념을 판단한다.\n글에 담긴 사회·문화적 이념도 무조건 믿지는 않아요. 지금 우리가 살아가는 상황에 맞는 생각인지 따져 보아야 해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":6,"end":19,"before":"생각보다 글자의 모양을 ","after":"생각을 "}]}},"pageSpecificReasons":true,"evidence":{"title":"사회·문화적 이념 평가","statement":"글에 담긴 사회·문화적 이념도 따져 읽는다. 오늘날 우리 상황에서 받아들일 수 있는지 판단한다.","explanation":"글에 담긴 사회·문화적 이념도 무조건 믿지는 않아요. 지금 우리가 살아가는 상황에 맞는 생각인지 따져 보아야 해요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","valid":["D22:5"],"sources":[{"id":"D22","title":"비판적 읽기와 다양한 읽기 방법","label":"교과서 49쪽 개념 발췌 정리","sentences":[{"id":"D22:1","text":"비판적 읽기는 글의 내용과 필자의 생각을 무조건 수용하지 않고, 글에 제시된 내용이 올바른지 따져 가며 읽는 것이다.","paragraph":0,"memberIds":["D22:1"],"topic":"비판적 읽기"},{"id":"D22:2","text":"내용의 타당성은 글에 나타난 주장이나 의견, 근거 등 글의 내용이 옳고 정확한지 살피는 기준이다.","paragraph":0,"memberIds":["D22:2"],"topic":"내용의 타당성"},{"id":"D22:3","text":"관점의 공정성은 필자가 글의 내용을 한쪽으로 치우치지 않고 균형 있게 다루는지 판단하는 기준이다.","paragraph":0,"memberIds":["D22:3"],"topic":"관점의 공정성"},{"id":"D22:4","text":"표현 방법의 적절성은 글의 목적과 내용에 비추어 표현 방법이 효과적이고 적절한지 평가하는 기준이다.","paragraph":0,"memberIds":["D22:4"],"topic":"표현 방법의 적절성"},{"id":"D22:5","text":"비판적 독자는 글에 반영된 사회·문화적 이념이 현재 우리의 상황에서 수용할 수 있는 것인지 판단한다.","paragraph":0,"memberIds":["D22:5"],"topic":"사회·문화적 이념"},{"id":"D22:6","text":"창의적 읽기는 문제 상황을 비판적으로 이해하고 유연한 사고로 발상을 전환하며 새로운 대안을 탐구하는 읽기이다.","paragraph":0,"memberIds":["D22:6"],"topic":"창의적 읽기"},{"id":"D22:7","text":"감상적 읽기는 글의 내용이나 필자의 생각에 공감하며 감동과 즐거움을 얻는 읽기이며, 서로 다른 감상을 공유하여 이해를 풍부하게 할 수 있다.","paragraph":0,"memberIds":["D22:7"],"topic":"감상적 읽기"}]}]},"editorSourceVersion":"753b0d9876e3203aac0389daa9164f848334234c513eaa6fc43795df7bfedeea"}]},{"name":"U22-10 · 125달러의 성격","items":[{"paragraphCount":1,"readingLabel":"2문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 2문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 2문단]\n많은 뉴요커들은 연극을 보고 싶었으나 줄을 설 시간이 없었다. 이런 곤란한 상황에서 작은 사업거리가 새로 등장했다. 편리를 얻는 대가로 기꺼이 비용을 지불할 의사가 있는 사람을 위해 대신 줄을 서고 입장권을 받아 주는 사업이었다. 이들은 온라인 사이트에 자신들의 서비스를 광고했고, 줄을 서서 기다리는 수고를 견뎌 내는 대가로 무료 공연 입장권에 한 장당 125달러의 수고비를 청구했다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["주체"],"id":"U22-10-S1","type":"mc","sent":"2문단의 내용과 맞는 설명은?","options":["125달러는 극장에 내는 공연 관람료다.","대리 줄 서기 사업자는 표를 구하려고 125달러를 낸다.","대리 줄 서기 사업자는 공연 표가 유료라서 125달러를 받는다.","125달러는 줄 서기와 상관없는 광고비다.","125달러는 대신 줄을 서 준 사람에게 주는 돈이다. 극장에 내는 공연 관람료가 아니다."],"answer":"125달러는 대신 줄을 서 준 사람에게 주는 돈이다. 극장에 내는 공연 관람료가 아니다.","why":"공연 표는 원래 무료예요. 125달러는 표를 나누어 주는 극장이 아니라, 대신 기다려 준 사업자가 받아요.\n2문단에서 확인할 수 있어요.","choiceReviews":{"125달러는 대신 줄을 서 준 사람에게 주는 돈이다. 극장에 내는 공연 관람료가 아니다.":{"reason":"공연 표는 원래 무료예요. 125달러는 표를 나누어 주는 극장이 아니라, 대신 기다려 준 사업자가 받아요.\n2문단에서 확인할 수 있어요.","edits":[]},"125달러는 극장에 내는 공연 관람료다.":{"reason":"바르게 고치면: 125달러는 대신 줄을 서 준 사람에게 주는 돈이다.\n공연 표는 원래 무료예요. 125달러는 표를 나누어 주는 극장이 아니라, 대신 기다려 준 사업자가 받아요.\n2문단에서 확인할 수 있어요.","edits":[{"start":7,"end":22,"before":"극장에 내는 공연 관람료다.","after":"대신 줄을 서 준 사람에게 주는 돈이다."}]},"대리 줄 서기 사업자는 표를 구하려고 125달러를 낸다.":{"reason":"바르게 고치면: 대리 줄 서기 사업자는 표를 받아 주고 125달러를 받는다.\n공연 표는 원래 무료예요. 125달러는 표를 나누어 주는 극장이 아니라, 대신 기다려 준 사업자가 받아요.\n2문단에서 확인할 수 있어요.","edits":[{"start":16,"end":21,"before":"구하려고 ","after":"받아 주고 "},{"start":28,"end":31,"before":"낸다.","after":"받는다."}]},"대리 줄 서기 사업자는 공연 표가 유료라서 125달러를 받는다.":{"reason":"바르게 고치면: 대리 줄 서기 사업자는 무료 표를 대신 줄 서서 받아 주고 125달러를 받는다.\n공연 표는 원래 무료예요. 125달러는 표를 나누어 주는 극장이 아니라, 대신 기다려 준 사업자가 받아요.\n2문단에서 확인할 수 있어요.","edits":[{"start":13,"end":24,"before":"공연 표가 유료라서 ","after":"무료 표를 대신 줄 서서 받아 주고 "}]},"125달러는 줄 서기와 상관없는 광고비다.":{"reason":"바르게 고치면: 125달러는 대신 줄을 서 준 사람에게 주는 돈이다.\n공연 표는 원래 무료예요. 125달러는 표를 나누어 주는 극장이 아니라, 대신 기다려 준 사업자가 받아요.\n2문단에서 확인할 수 있어요.","edits":[{"start":7,"end":23,"before":"줄 서기와 상관없는 광고비다.","after":"대신 줄을 서 준 사람에게 주는 돈이다."}]}},"pageSpecificReasons":true,"evidence":{"title":"125달러의 성격","statement":"125달러는 대신 줄을 서 준 사람에게 주는 돈이다. 극장에 내는 공연 관람료가 아니다.","explanation":"공연 표는 원래 무료예요. 125달러는 표를 나누어 주는 극장이 아니라, 대신 기다려 준 사업자가 받아요.\n2문단에서 확인할 수 있어요.","valid":["L02:4"],"sources":[{"id":"L02","title":"줄 서기를 돈으로 살 수 있을까","label":"2문단","sentences":[{"id":"L02:1","text":"많은 뉴요커들은 연극을 보고 싶었으나 줄을 설 시간이 없었다.","paragraph":0,"memberIds":["L02:1"],"topic":"연극을 보고 싶은 뉴욕 사람은 많았다. 그런데 바빠서 줄 설 시간이 없었다."},{"id":"L02:2","text":"이런 곤란한 상황에서 작은 사업거리가 새로 등장했다.","paragraph":0,"memberIds":["L02:2"],"topic":"그러자 새로운 작은 사업이 생겼다."},{"id":"L02:3","text":"편리를 얻는 대가로 기꺼이 비용을 지불할 의사가 있는 사람을 위해 대신 줄을 서고 입장권을 받아 주는 사업이었다.","paragraph":0,"memberIds":["L02:3"],"topic":"어떤 사람들은 돈을 내서라도 편하게 표를 받고 싶었다. 그 사람 대신 줄을 서서 표를 받아다 주는 일이었다."},{"id":"L02:4","text":"이들은 온라인 사이트에 자신들의 서비스를 광고했고, 줄을 서서 기다리는 수고를 견뎌 내는 대가로 무료 공연 입장권에 한 장당 125달러의 수고비를 청구했다.","paragraph":0,"memberIds":["L02:4"],"topic":"이 사람들은 인터넷에 광고를 올렸다. 그리고 공짜 표 한 장을 받아 주는 값으로 125달러(우리 돈 십수만 원)를 달라고 했다(청구했다). 줄 서서 기다린 고생값(수고비)이라는 것이다."}]}]},"editorSourceVersion":"343d563dcd16ccf299332357fdc28fc2996e8439ab1f8d51aca791d018cd46da"}]},{"name":"U22-12 · 극장과 쿠오모의 반대 근거","items":[{"paragraphCount":1,"readingLabel":"3문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 3문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 3문단]\n극장 측은 “공원에서 이루어지는 줄 서기 대리 행위는 셰익스피어 정신에 어긋난다.”라고 주장하면서 대리로 줄을 서 주는 사람들의 영업을 막기 위해 노력했다. 국가 보조금을 받는 비영리 사업체인 퍼블릭 시어터의 사명은 모든 계층의 시민이 훌륭한 극장 시설을 이용할 수 있게 하는 것이다. 당시 뉴욕 검찰 총장이었던 앤드루 쿠오모(Andrew Cuomo)는 온라인 사이트에 압력을 가해 대리 줄 서기로 입장권을 구해 준다는 광고를 중단하게 했다. 그러면서 그는 이렇게 강조했다. “무료여야 하는 입장권을 판매하는 행위는 기관이 납세자의 후원을 받아 제공하는 혜택을 누릴 뉴요커의 권리를 침해한다.” 사람을 고용해 대리로 줄을 세우거나 암표를 파는 행동이 잘못일까?","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["주체"],"id":"U22-12-S1","type":"mc","sent":"3문단의 내용과 맞는 설명은?","options":["쿠오모는 대리 줄 서기가 셰익스피어 정신에 어긋난다고 말했다.","극장은 대리 줄 서기가 셰익스피어 정신에 어긋난다고 본다. 쿠오모는 대리 줄 서기가 시민의 권리를 해친다고 본다.","극장은 대리 줄 서기가 셰익스피어 정신에 맞는다고 본다.","쿠오모는 대리 줄 서기가 시민의 혜택을 늘린다고 본다.","시민의 권리를 해친다고 말한 사람은 극장 관계자다."],"answer":"극장은 대리 줄 서기가 셰익스피어 정신에 어긋난다고 본다. 쿠오모는 대리 줄 서기가 시민의 권리를 해친다고 본다.","why":"극장과 쿠오모는 모두 대리 줄 서기에 반대해요. 극장은 셰익스피어 정신을, 쿠오모는 세금으로 지원하는 공연을 누릴 시민의 권리를 이유로 들어요.\n3문단에서 확인할 수 있어요.","choiceReviews":{"극장은 대리 줄 서기가 셰익스피어 정신에 어긋난다고 본다. 쿠오모는 대리 줄 서기가 시민의 권리를 해친다고 본다.":{"reason":"극장과 쿠오모는 모두 대리 줄 서기에 반대해요. 극장은 셰익스피어 정신을, 쿠오모는 세금으로 지원하는 공연을 누릴 시민의 권리를 이유로 들어요.\n3문단에서 확인할 수 있어요.","edits":[]},"쿠오모는 대리 줄 서기가 셰익스피어 정신에 어긋난다고 말했다.":{"reason":"바르게 고치면: 극장은 대리 줄 서기가 셰익스피어 정신에 어긋난다고 말했다.\n극장과 쿠오모는 모두 대리 줄 서기에 반대해요. 극장은 셰익스피어 정신을, 쿠오모는 세금으로 지원하는 공연을 누릴 시민의 권리를 이유로 들어요.\n3문단에서 확인할 수 있어요.","edits":[{"start":0,"end":5,"before":"쿠오모는 ","after":"극장은 "}]},"극장은 대리 줄 서기가 셰익스피어 정신에 맞는다고 본다.":{"reason":"바르게 고치면: 극장은 대리 줄 서기가 셰익스피어 정신에 어긋난다고 본다.\n극장과 쿠오모는 모두 대리 줄 서기에 반대해요. 극장은 셰익스피어 정신을, 쿠오모는 세금으로 지원하는 공연을 누릴 시민의 권리를 이유로 들어요.\n3문단에서 확인할 수 있어요.","edits":[{"start":23,"end":28,"before":"맞는다고 ","after":"어긋난다고 "}]},"쿠오모는 대리 줄 서기가 시민의 혜택을 늘린다고 본다.":{"reason":"바르게 고치면: 쿠오모는 대리 줄 서기가 시민의 권리를 해친다고 본다.\n극장과 쿠오모는 모두 대리 줄 서기에 반대해요. 극장은 셰익스피어 정신을, 쿠오모는 세금으로 지원하는 공연을 누릴 시민의 권리를 이유로 들어요.\n3문단에서 확인할 수 있어요.","edits":[{"start":18,"end":27,"before":"혜택을 늘린다고 ","after":"권리를 해친다고 "}]},"시민의 권리를 해친다고 말한 사람은 극장 관계자다.":{"reason":"바르게 고치면: 시민의 권리를 해친다고 말한 사람은 쿠오모다.\n극장과 쿠오모는 모두 대리 줄 서기에 반대해요. 극장은 셰익스피어 정신을, 쿠오모는 세금으로 지원하는 공연을 누릴 시민의 권리를 이유로 들어요.\n3문단에서 확인할 수 있어요.","edits":[{"start":20,"end":28,"before":"극장 관계자다.","after":"쿠오모다."}]}},"pageSpecificReasons":true,"evidence":{"title":"극장과 쿠오모의 반대 근거","statement":"극장은 대리 줄 서기가 셰익스피어 정신에 어긋난다고 본다. 쿠오모는 대리 줄 서기가 시민의 권리를 해친다고 본다.","explanation":"극장과 쿠오모는 모두 대리 줄 서기에 반대해요. 극장은 셰익스피어 정신을, 쿠오모는 세금으로 지원하는 공연을 누릴 시민의 권리를 이유로 들어요.\n3문단에서 확인할 수 있어요.","valid":["L03:1","L03:5"],"sources":[{"id":"L03","title":"줄 서기를 돈으로 살 수 있을까","label":"3문단","sentences":[{"id":"L03:1","text":"극장 측은 “공원에서 이루어지는 줄 서기 대리 행위는 셰익스피어 정신에 어긋난다.”라고 주장하면서 대리로 줄을 서 주는 사람들의 영업을 막기 위해 노력했다.","paragraph":0,"memberIds":["L03:1"],"topic":"극장은 \"대신 줄 서 주는 건 셰익스피어 정신(이 공연의 정신)과 맞지 않는다.\"라고 말했다. 그리고 그 사업을 막으려고 애썼다."},{"id":"L03:2","text":"국가 보조금을 받는 비영리 사업체인 퍼블릭 시어터의 사명은 모든 계층의 시민이 훌륭한 극장 시설을 이용할 수 있게 하는 것이다.","paragraph":0,"memberIds":["L03:2"],"topic":"이 극장은 돈을 벌려고 만든 곳이 아니다(비영리). 나라가 세금으로 돈도 대 준다(보조금). 극장이 꼭 해야 할 일(사명)은 부자든 아니든 모든 시민이 좋은 공연을 보게 하는 것이다."},{"id":"L03:3","text":"당시 뉴욕 검찰 총장이었던 앤드루 쿠오모(Andrew Cuomo)는 온라인 사이트에 압력을 가해 대리 줄 서기로 입장권을 구해 준다는 광고를 중단하게 했다.","paragraph":0,"memberIds":["L03:3"],"topic":"뉴욕 검찰 총장 쿠오모도 나섰다. 인터넷 사이트를 압박해서 그 광고를 내리게 했다."},{"id":"L03:4","text":"그러면서 그는 이렇게 강조했다.","paragraph":0,"memberIds":["L03:4"],"topic":"그리고 이렇게 말했다."},{"id":"L03:5","text":"“무료여야 하는 입장권을 판매하는 행위는 기관이 납세자의 후원을 받아 제공하는 혜택을 누릴 뉴요커의 권리를 침해한다.”","paragraph":0,"memberIds":["L03:5"],"topic":"\"이 공연은 시민이 낸 세금의 도움으로 여는 혜택이다. 그러니 뉴욕 시민 누구나 누릴 권리가 있다. 공짜여야 할 표를 파는 건 그 권리를 빼앗는(침해하는) 일이다.\""},{"id":"L03:6","text":"사람을 고용해 대리로 줄을 세우거나 암표를 파는 행동이 잘못일까?","paragraph":0,"memberIds":["L03:6"],"topic":"그렇다면 돈을 주고 사람을 시켜 대신 줄을 세우거나, 표를 비싸게 되파는(암표) 건 정말 잘못일까?"}]}]},"editorSourceVersion":"e5c20fb75a57825160a238bd174cc28ce33c8bbb7c74b89a7dc76fed57ee12c9"}]},{"name":"U22-13 · 마지막 문장의 질문 형식","items":[{"paragraphCount":1,"readingLabel":"3문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 3문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 3문단]\n극장 측은 “공원에서 이루어지는 줄 서기 대리 행위는 셰익스피어 정신에 어긋난다.”라고 주장하면서 대리로 줄을 서 주는 사람들의 영업을 막기 위해 노력했다. 국가 보조금을 받는 비영리 사업체인 퍼블릭 시어터의 사명은 모든 계층의 시민이 훌륭한 극장 시설을 이용할 수 있게 하는 것이다. 당시 뉴욕 검찰 총장이었던 앤드루 쿠오모(Andrew Cuomo)는 온라인 사이트에 압력을 가해 대리 줄 서기로 입장권을 구해 준다는 광고를 중단하게 했다. 그러면서 그는 이렇게 강조했다. “무료여야 하는 입장권을 판매하는 행위는 기관이 납세자의 후원을 받아 제공하는 혜택을 누릴 뉴요커의 권리를 침해한다.” 사람을 고용해 대리로 줄을 세우거나 암표를 파는 행동이 잘못일까?","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["주체"],"id":"U22-13-S1","type":"mc","sent":"3문단의 내용과 맞는 설명은?","options":["3문단 끝에서는 대리 줄 서기가 잘못이라고 결론을 내린다.","3문단 끝에서는 암표 판매가 잘못이라고 단정한다.","3문단 끝에서는 대리 줄 서기와 암표 판매가 잘못인지 묻는다. 잘못이라고 결론을 내리지는 않는다.","3문단 끝에서는 대리 줄 서기를 어떻게 광고할지 묻는다.","3문단 끝에서는 정부가 극장을 지원하는 일이 잘못인지 묻는다."],"answer":"3문단 끝에서는 대리 줄 서기와 암표 판매가 잘못인지 묻는다. 잘못이라고 결론을 내리지는 않는다.","why":"마지막 문장은 대리 줄 서기와 암표 판매가 잘못인지 독자에게 물어요. 여기서는 질문을 던졌을 뿐, 답을 정하지 않았어요.\n3문단에서 확인할 수 있어요.","choiceReviews":{"3문단 끝에서는 대리 줄 서기와 암표 판매가 잘못인지 묻는다. 잘못이라고 결론을 내리지는 않는다.":{"reason":"마지막 문장은 대리 줄 서기와 암표 판매가 잘못인지 독자에게 물어요. 여기서는 질문을 던졌을 뿐, 답을 정하지 않았어요.\n3문단에서 확인할 수 있어요.","edits":[]},"3문단 끝에서는 대리 줄 서기가 잘못이라고 결론을 내린다.":{"reason":"바르게 고치면: 3문단 끝에서는 대리 줄 서기가 잘못인지 묻는다.\n마지막 문장은 대리 줄 서기와 암표 판매가 잘못인지 독자에게 물어요. 여기서는 질문을 던졌을 뿐, 답을 정하지 않았어요.\n3문단에서 확인할 수 있어요.","edits":[{"start":18,"end":32,"before":"잘못이라고 결론을 내린다.","after":"잘못인지 묻는다."}]},"3문단 끝에서는 암표 판매가 잘못이라고 단정한다.":{"reason":"바르게 고치면: 3문단 끝에서는 암표 판매가 잘못인지 묻는다.\n마지막 문장은 대리 줄 서기와 암표 판매가 잘못인지 독자에게 물어요. 여기서는 질문을 던졌을 뿐, 답을 정하지 않았어요.\n3문단에서 확인할 수 있어요.","edits":[{"start":16,"end":27,"before":"잘못이라고 단정한다.","after":"잘못인지 묻는다."}]},"3문단 끝에서는 대리 줄 서기를 어떻게 광고할지 묻는다.":{"reason":"바르게 고치면: 3문단 끝에서는 대리 줄 서기가 잘못인지 묻는다.\n마지막 문장은 대리 줄 서기와 암표 판매가 잘못인지 독자에게 물어요. 여기서는 질문을 던졌을 뿐, 답을 정하지 않았어요.\n3문단에서 확인할 수 있어요.","edits":[{"start":14,"end":27,"before":"서기를 어떻게 광고할지 ","after":"서기가 잘못인지 "}]},"3문단 끝에서는 정부가 극장을 지원하는 일이 잘못인지 묻는다.":{"reason":"바르게 고치면: 3문단 끝에서는 대리 줄 서기와 암표 판매가 잘못인지 묻는다.\n마지막 문장은 대리 줄 서기와 암표 판매가 잘못인지 독자에게 물어요. 여기서는 질문을 던졌을 뿐, 답을 정하지 않았어요.\n3문단에서 확인할 수 있어요.","edits":[{"start":9,"end":25,"before":"정부가 극장을 지원하는 일이 ","after":"대리 줄 서기와 암표 판매가 "}]}},"pageSpecificReasons":true,"evidence":{"title":"마지막 문장의 질문 형식","statement":"3문단 끝에서는 대리 줄 서기와 암표 판매가 잘못인지 묻는다. 잘못이라고 결론을 내리지는 않는다.","explanation":"마지막 문장은 대리 줄 서기와 암표 판매가 잘못인지 독자에게 물어요. 여기서는 질문을 던졌을 뿐, 답을 정하지 않았어요.\n3문단에서 확인할 수 있어요.","valid":["L03:6"],"sources":[{"id":"L03","title":"줄 서기를 돈으로 살 수 있을까","label":"3문단","sentences":[{"id":"L03:1","text":"극장 측은 “공원에서 이루어지는 줄 서기 대리 행위는 셰익스피어 정신에 어긋난다.”라고 주장하면서 대리로 줄을 서 주는 사람들의 영업을 막기 위해 노력했다.","paragraph":0,"memberIds":["L03:1"],"topic":"극장은 \"대신 줄 서 주는 건 셰익스피어 정신(이 공연의 정신)과 맞지 않는다.\"라고 말했다. 그리고 그 사업을 막으려고 애썼다."},{"id":"L03:2","text":"국가 보조금을 받는 비영리 사업체인 퍼블릭 시어터의 사명은 모든 계층의 시민이 훌륭한 극장 시설을 이용할 수 있게 하는 것이다.","paragraph":0,"memberIds":["L03:2"],"topic":"이 극장은 돈을 벌려고 만든 곳이 아니다(비영리). 나라가 세금으로 돈도 대 준다(보조금). 극장이 꼭 해야 할 일(사명)은 부자든 아니든 모든 시민이 좋은 공연을 보게 하는 것이다."},{"id":"L03:3","text":"당시 뉴욕 검찰 총장이었던 앤드루 쿠오모(Andrew Cuomo)는 온라인 사이트에 압력을 가해 대리 줄 서기로 입장권을 구해 준다는 광고를 중단하게 했다.","paragraph":0,"memberIds":["L03:3"],"topic":"뉴욕 검찰 총장 쿠오모도 나섰다. 인터넷 사이트를 압박해서 그 광고를 내리게 했다."},{"id":"L03:4","text":"그러면서 그는 이렇게 강조했다.","paragraph":0,"memberIds":["L03:4"],"topic":"그리고 이렇게 말했다."},{"id":"L03:5","text":"“무료여야 하는 입장권을 판매하는 행위는 기관이 납세자의 후원을 받아 제공하는 혜택을 누릴 뉴요커의 권리를 침해한다.”","paragraph":0,"memberIds":["L03:5"],"topic":"\"이 공연은 시민이 낸 세금의 도움으로 여는 혜택이다. 그러니 뉴욕 시민 누구나 누릴 권리가 있다. 공짜여야 할 표를 파는 건 그 권리를 빼앗는(침해하는) 일이다.\""},{"id":"L03:6","text":"사람을 고용해 대리로 줄을 세우거나 암표를 파는 행동이 잘못일까?","paragraph":0,"memberIds":["L03:6"],"topic":"그렇다면 돈을 주고 사람을 시켜 대신 줄을 세우거나, 표를 비싸게 되파는(암표) 건 정말 잘못일까?"}]}]},"editorSourceVersion":"58a94cc4ed98138dfde6c1eed8933322b74e06dffb4e5f0d14dddbabffb44a92"}]},{"name":"U22-14 · 시장 옹호의 두 논거","items":[{"paragraphCount":1,"readingLabel":"4문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 4문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 4문단]\n줄 서기에 관해 시장을 옹호하는 입장에는 두 가지 주장이 있다. 하나는 개인의 자유 존중에 대한 것이고, 다른 하나는 행복이나 사회적 효용의 극대화에 대한 주장이다. 첫 번째는 자유 지상주의자의 입장이다. 그들은 타인의 권리를 침범하지 않는 한 원하는 재화는 무엇이든 자유롭게 사고팔 수 있어야 한다고 주장한다. 자유 지상주의자는 장기 매매 금지법에 반대하는 것과 같은 이유로 암표 매매 금지법에 반대한다. 이러한 법은 성인이 상호 동의에 따라 내린 선택을 방해함으로써 개인의 자유를 침해한다고 믿기 때문이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["주체"],"id":"U22-14-S1","type":"mc","sent":"4문단의 내용과 맞는 설명은?","options":["자유 지상주의는 개인의 자유보다 사회 전체의 행복을 더 중요하게 여긴다.","시장을 지지하는 두 가지 이유는 극장의 수입과 비싼 표부터 파는 일이다.","자유 지상주의자는 개인의 자유를 중요하게 여기지 않는다.","시장을 지지하는 사람들은 개인의 자유를 존중하고 사회 전체의 행복을 늘릴 수 있다고 말한다. 이 가운데 자유 지상주의는 개인의 자유를 가장 중요하게 여긴다.","이 문단의 두 가지 이유는 시장 거래에 반대할 때 쓰인다."],"answer":"시장을 지지하는 사람들은 개인의 자유를 존중하고 사회 전체의 행복을 늘릴 수 있다고 말한다. 이 가운데 자유 지상주의는 개인의 자유를 가장 중요하게 여긴다.","why":"자유롭게 거래할 수 있어야 한다는 주장을 두 가지 이유로 뒷받침해요. 개인의 자유를 지켜야 한다는 이유와 사회 전체가 더 행복해진다는 이유예요.\n4문단에서 확인할 수 있어요.","choiceReviews":{"시장을 지지하는 사람들은 개인의 자유를 존중하고 사회 전체의 행복을 늘릴 수 있다고 말한다. 이 가운데 자유 지상주의는 개인의 자유를 가장 중요하게 여긴다.":{"reason":"자유롭게 거래할 수 있어야 한다는 주장을 두 가지 이유로 뒷받침해요. 개인의 자유를 지켜야 한다는 이유와 사회 전체가 더 행복해진다는 이유예요.\n4문단에서 확인할 수 있어요.","edits":[]},"자유 지상주의는 개인의 자유보다 사회 전체의 행복을 더 중요하게 여긴다.":{"reason":"바르게 고치면: 자유 지상주의는 개인의 자유를 가장 중요하게 여긴다.\n자유롭게 거래할 수 있어야 한다는 주장을 두 가지 이유로 뒷받침해요. 개인의 자유를 지켜야 한다는 이유와 사회 전체가 더 행복해진다는 이유예요.\n4문단에서 확인할 수 있어요.","edits":[{"start":13,"end":31,"before":"자유보다 사회 전체의 행복을 더 ","after":"자유를 가장 "}]},"시장을 지지하는 두 가지 이유는 극장의 수입과 비싼 표부터 파는 일이다.":{"reason":"바르게 고치면: 시장을 지지하는 두 가지 이유는 개인의 자유와 사회 전체의 행복이다.\n자유롭게 거래할 수 있어야 한다는 주장을 두 가지 이유로 뒷받침해요. 개인의 자유를 지켜야 한다는 이유와 사회 전체가 더 행복해진다는 이유예요.\n4문단에서 확인할 수 있어요.","edits":[{"start":18,"end":40,"before":"극장의 수입과 비싼 표부터 파는 일이다.","after":"개인의 자유와 사회 전체의 행복이다."}]},"자유 지상주의자는 개인의 자유를 중요하게 여기지 않는다.":{"reason":"바르게 고치면: 자유 지상주의자는 개인의 자유를 가장 중요하게 여긴다.\n자유롭게 거래할 수 있어야 한다는 주장을 두 가지 이유로 뒷받침해요. 개인의 자유를 지켜야 한다는 이유와 사회 전체가 더 행복해진다는 이유예요.\n4문단에서 확인할 수 있어요.","edits":[{"start":14,"end":18,"before":"자유를 ","after":"자유를 가장 "},{"start":23,"end":31,"before":"여기지 않는다.","after":"여긴다."}]},"이 문단의 두 가지 이유는 시장 거래에 반대할 때 쓰인다.":{"reason":"바르게 고치면: 이 문단의 두 가지 이유는 시장 거래에 찬성할 때 쓰인다.\n자유롭게 거래할 수 있어야 한다는 주장을 두 가지 이유로 뒷받침해요. 개인의 자유를 지켜야 한다는 이유와 사회 전체가 더 행복해진다는 이유예요.\n4문단에서 확인할 수 있어요.","edits":[{"start":22,"end":26,"before":"반대할 ","after":"찬성할 "}]}},"pageSpecificReasons":true,"evidence":{"title":"시장 옹호의 두 논거","statement":"시장을 지지하는 사람들은 개인의 자유를 존중하고 사회 전체의 행복을 늘릴 수 있다고 말한다. 이 가운데 자유 지상주의는 개인의 자유를 가장 중요하게 여긴다.","explanation":"자유롭게 거래할 수 있어야 한다는 주장을 두 가지 이유로 뒷받침해요. 개인의 자유를 지켜야 한다는 이유와 사회 전체가 더 행복해진다는 이유예요.\n4문단에서 확인할 수 있어요.","valid":["L04:2","L04:3"],"sources":[{"id":"L04","title":"줄 서기를 돈으로 살 수 있을까","label":"4문단","sentences":[{"id":"L04:1","text":"줄 서기에 관해 시장을 옹호하는 입장에는 두 가지 주장이 있다.","paragraph":0,"memberIds":["L04:1"],"topic":"돈으로 줄을 사는 것(시장)에 찬성하는 쪽의 이유는 두 가지다."},{"id":"L04:2","text":"하나는 개인의 자유 존중에 대한 것이고, 다른 하나는 행복이나 사회적 효용의 극대화에 대한 주장이다.","paragraph":0,"memberIds":["L04:2"],"topic":"첫째는 '개인의 자유를 존중하자'는 것이다. 둘째는 '사람들의 만족(효용)을 가장 크게 만들자'는 것이다."},{"id":"L04:3","text":"첫 번째는 자유 지상주의자의 입장이다.","paragraph":0,"memberIds":["L04:3"],"topic":"첫째 이유는 '자유 지상주의자'의 생각이다. 개인의 자유를 무엇보다 중요하게 여기는 사람들이다."},{"id":"L04:4","text":"그들은 타인의 권리를 침범하지 않는 한 원하는 재화는 무엇이든 자유롭게 사고팔 수 있어야 한다고 주장한다.","paragraph":0,"memberIds":["L04:4"],"topic":"그들은 이렇게 말한다. \"남의 권리를 침범하지(피해를 주지) 않는 한, 무엇이든 자유롭게 사고팔 수 있어야 한다.\""},{"id":"L04:5","text":"자유 지상주의자는 장기 매매 금지법에 반대하는 것과 같은 이유로 암표 매매 금지법에 반대한다.","paragraph":0,"memberIds":["L04:5"],"topic":"그래서 그들은 '암표를 팔지 마라'는 법에 반대한다. '장기를 사고팔지 마라'는 법에 반대하는 것과 같은 이유에서다."},{"id":"L04:6","text":"이러한 법은 성인이 상호 동의에 따라 내린 선택을 방해함으로써 개인의 자유를 침해한다고 믿기 때문이다.","paragraph":0,"memberIds":["L04:6"],"topic":"어른 둘이 서로 좋다고 합의한 거래를 법이 막으면, 개인의 자유를 빼앗는 것이라고 믿기 때문이다."}]}]},"editorSourceVersion":"422f5a2a38fd017d15ba43a9cf9598796c0423c4125fb40998ef3799db1258ec"}]}]};})(window);
